package com.saasquatch.intelligence.service; import com.saasquatch.intelligence.dto.*; import com.saasquatch.intelligence.entity.*; import com.saasquatch.intelligence.intelligence.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class ScoringService { private final OpportunityScoringEngine engine=new OpportunityScoringEngine(); public LeadIntelligenceResponse intelligence(Lead l,List<CorporateRelationship> rels){var b=engine.breakdown(l); int score=Math.min(100,b.revenuePotential()+b.growth()+b.technologyFit()+b.decisionMaker()+b.industryFit()+b.corporateRelationship()+b.dataConfidence()); var signals=l.getSignals().stream().map(s->new SignalResponse(s.getType().name(),s.getWeight(),s.getDescription())).toList(); String why=signals.stream().limit(3).map(SignalResponse::description).reduce((a,x)->a+"; "+x).orElse("Strong account profile and verified lead data."); String action=l.isDecisionMaker()?"Contact "+l.getTitle()+" today":"Verify the decision maker, then start a targeted outreach sequence"; List<String> cr=rels.stream().map(r->r.getType()+" → "+r.getRelatedCompany().getName()+": "+r.getDescription()).toList(); return new LeadIntelligenceResponse(l.getId(),l.getCompany().getName(),l.getContactName(),l.getTitle(),score,why,action,l.getDataConfidence(),b,signals,cr); } }